VOICE.neil.fwyShort = ['Short. Fairway, not the green.', 'Came up short of the green.', 'Needed a bit more.']; VOICE.neil.fwyLong = ['Through the green. Hmm.', 'Flew the green.', 'Too much club.']; VOICE.neil.fwyMissed = ['Missed the green.', 'Fairway. Not where I was aiming.']; /* FWY_MOOD: everyone falls back to these */
