  const tu = P.u + P.dir.u * P.D, tv = P.v + P.dir.v * P.D; if (Math.hypot(tu - PIN.u, tv - PIN.v) > 12 && lieAt(tu, tv) !== 'green') return null; /* a lay-up: the fairway is the plan */
